// One-time (and incremental) mood tagging: genres/themes come from IGDB, but "mood" tags (cozy, dark...)
// are generated by the LLM from a fixed vocabulary. Only games without any mood tag are processed.
// --redo re-tags games tagged before IGDB keywords were part of the input (external_ids.mood_v < 2), replacing
// their moods; it is resumable, so a full redo can be split over days (~100K heavy tokens per 1,000 games).
// Usage: npx tsx scripts/mood-tags.ts [--limit 2000] [--redo]
import "./env";
import { q, closeDb } from "./db";
import { groqJson } from "../lib/llm/groq";
import { tagsFromKeywords } from "../lib/igdb/enrich";

export const MOODS = [
  "cozy", "relaxing", "wholesome", "funny", "chill", "creative",
  "dark", "gritty", "scary", "tense", "intense", "fast-paced", "competitive", "challenging",
  "atmospheric", "mysterious", "emotional", "story-rich", "epic", "adventurous", "strategic", "nostalgic",
];
const BATCH = 30;

const limitArg = process.argv.indexOf("--limit");
const LIMIT = limitArg > 0 ? Number(process.argv[limitArg + 1]) : 5000;
const REDO = process.argv.includes("--redo");
const MOOD_VERSION = 2;

async function main() {
  for (const m of MOODS) {
    await q(`INSERT INTO tags (name, kind) VALUES ($1, 'mood') ON CONFLICT (name) DO NOTHING`, [m]);
  }
  const moodIds = new Map(
    (await q<{ id: number; name: string }>(`SELECT id, name FROM tags WHERE kind = 'mood'`)).map((r) => [r.name, r.id]),
  );
  const games = await q<{ id: string; title: string; tags: string; summary: string | null; keywords: string[] }>(
    `SELECT g.id, g.title, left(g.summary, 100) AS summary,
            (SELECT string_agg(t.name, ', ') FROM game_tags gt JOIN tags t ON t.id = gt.tag_id
             WHERE gt.game_id = g.id AND t.kind IN ('genre','theme')) AS tags,
            ARRAY(SELECT jsonb_array_elements_text(COALESCE(g.external_ids->'igdb_keywords', '[]'))) AS keywords
     FROM games g
     WHERE ${REDO
       ? `COALESCE((g.external_ids->>'mood_v')::int, 1) < ${MOOD_VERSION}`
       : `NOT EXISTS (SELECT 1 FROM game_tags gt JOIN tags t ON t.id = gt.tag_id WHERE gt.game_id = g.id AND t.kind = 'mood')`}
     ORDER BY g.popularity DESC LIMIT $1`,
    [LIMIT],
  );
  console.log(`${games.length} games need mood tags`);
  let tokens = 0;
  let tagged = 0;
  for (let i = 0; i < games.length; i += BATCH) {
    const batch = games.slice(i, i + BATCH);
    const lines = batch.map((g) => `${g.id}|${g.title}|${g.tags ?? ""}|${g.keywords.slice(0, 8).join(", ")}|${g.summary ?? ""}`).join("\n");
    const { data, tokens: t } = await groqJson<{ r: { id: number; m: string[] }[] }>("heavy", [
      {
        role: "system",
        content:
          `You tag PC games with 2-4 moods. Allowed moods only: ${MOODS.join(", ")}. ` +
          `Judge how the game actually feels to play, not the summary's tone. ` +
          `Input lines are id|title|genres/themes|keywords|summary. Respond with JSON {"r":[{"id":<id>,"m":["mood",...]}]} covering every id.`,
      },
      { role: "user", content: lines },
    ], { maxTokens: 2500, timeoutMs: 60000, retries: 6 });
    tokens += t;
    for (const row of data.r ?? []) {
      const game = batch.find((g) => Number(g.id) === Number(row.id));
      if (!game) continue;
      if (REDO) {
        await q(`DELETE FROM game_tags gt USING tags t WHERE gt.tag_id = t.id AND t.kind = 'mood' AND gt.game_id = $1`, [row.id]);
        // Moods that IGDB keywords state outright ("difficult", "dark fantasy") are kept alongside the LLM's.
        for (const t of tagsFromKeywords(game.keywords).filter((t) => t.kind === "mood")) {
          const tagId = moodIds.get(t.name);
          if (tagId) await q(`INSERT INTO game_tags (game_id, tag_id) VALUES ($1, $2) ON CONFLICT DO NOTHING`, [row.id, tagId]);
        }
      }
      await q(`UPDATE games SET external_ids = external_ids || jsonb_build_object('mood_v', ${MOOD_VERSION}) WHERE id = $1`, [row.id]);
      for (const m of (row.m ?? []).slice(0, 4)) {
        const tagId = moodIds.get(String(m).toLowerCase());
        if (tagId) await q(`INSERT INTO game_tags (game_id, tag_id) VALUES ($1, $2) ON CONFLICT DO NOTHING`, [row.id, tagId]);
      }
      tagged++;
    }
    console.log(`  ${Math.min(i + BATCH, games.length)}/${games.length} (tokens so far ${tokens})`);
    await new Promise((res) => setTimeout(res, 20000)); // stay under 8K tokens/min
  }
  console.log(`tagged ${tagged} games, ${tokens} tokens`);
  await closeDb();
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});
